    function handleAddStaff(e) {
      e.preventDefault();
      var nameInput = document.getElementById('newStaffName');
      var phoneInput = document.getElementById('newStaffPhone');
      var pinInput = document.getElementById('newStaffPin');
      var name = (nameInput ? nameInput.value : '').trim();
      var rawPhone = (phoneInput ? phoneInput.value : '').trim();
      var phone = normalizeIndianMobile(rawPhone);
      var pin = (pinInput ? pinInput.value : '').trim();

      if (!rawPhone || !isValidIndianMobile(phone)) {
        alert('Please enter a valid 10-digit Indian mobile number for staff starting with 6, 7, 8, or 9.');
        if (phoneInput) phoneInput.focus();
        return;
      }

      // Check mobile number uniqueness among staff (proof of identity)
      var duplicateStaff = (state.staffList || []).find(function(s) {
        return s.phone && normalizeIndianMobile(s.phone) === phone;
      });
      if (duplicateStaff) {
        alert('Mobile number ' + formatIndianMobile(phone) + ' is already registered to staff member "' + duplicateStaff.name + '" (ID: ' + duplicateStaff.id + ').\n\nStaff mobile number serves as proof of identity and must be unique.');
        if (phoneInput) phoneInput.focus();
        return;
      }
      var idEl = document.getElementById('newStaffId');
      var id = idEl ? idEl.value.trim() : '';

      if (!name) return;
      if (!pin || !/^\d{6}$/.test(pin)) {
        alert('Please enter a 6-digit login PIN for new staff.');
        if (pinInput) pinInput.focus();
        return;
      }

      var addWt = (document.getElementById('newStaffWorkType') ? document.getElementById('newStaffWorkType').value : 'dcc_only') || 'dcc_only';
      var addDesig = (document.getElementById('newStaffDesignation') ? document.getElementById('newStaffDesignation').value : 'cleaner') || 'cleaner';
      var addCaps = ['daily_car_cleaning'];
      if (addWt === 'dcc_and_services') {
        addCaps = ['daily_car_cleaning', 'car_washing'];
      } else if (addWt === 'services_only') {
        addCaps = ['car_washing'];
      }
      var staffPayload = {
        name: name,
        id: id,
        phone: phone,
        pin: pin,
        active: true,
        workType: addWt,
        serviceCapabilities: addCaps,
        designationId: addDesig
      };
      if (state.newStaffPhotoObj) {
        staffPayload.photoObj = state.newStaffPhotoObj;
      }

      apiCall('saveStaffMember', { staffData: staffPayload }, function(res) {
        if (nameInput) nameInput.value = '';
        if (phoneInput) phoneInput.value = '';
        if (pinInput) pinInput.value = '';
        if (idEl) idEl.value = '';
        clearNewStaffPhoto();
        closeAddStaffModal();
        showToast('Staff member "' + name + '" added successfully!', '✓');
        if (res && res.staffList) {
          populateAdminStaffList(res.staffList);
        } else {
          loadStaffListForAdmin();
        }
      }, function(err) {
        showToast('Error: ' + (err.message || err), '❌');
      });
    }

    function handleDeleteStaff(id) {
      var staff = (state.staffList || []).find(function(s) {
        return (s.id || '').toUpperCase() === (id || '').toUpperCase();
      });
      var staffName = staff ? staff.name : ('Staff ' + id);

      if (!confirm('Are you sure you want to delete staff member "' + staffName + '"?\n\nThis will deactivate their account, revoke all active login sessions, and unassign their customer route sequences.')) return;

      closeEditStaffModal();

      apiCall('deleteStaffMember', { id: id }, function(res) {
        showToast('Staff member "' + staffName + '" deleted successfully', '✓');
        var updatedList = res && res.staffList ? res.staffList : null;
        if (updatedList) {
          state.staffList = updatedList;
          state.adminStaffList = updatedList;
          populateAdminStaffList(updatedList);
          populateSeqStaffDropdown(updatedList);
          populateStaffFilterDropdown();
        } else {
          loadStaffListForAdmin();
        }
        loadAdminRecords(true);
        if (state.seqManagement) {
          initAdminSequenceManager();
        }
      }, function(err) {
        showToast('Error: ' + (err.message || err), '❌');
      });
    }

    function handleDeleteStaffFromModal() {
      var staffId = (document.getElementById('editStaffId') && document.getElementById('editStaffId').value) || '';
      if (!staffId) {
        showToast('Staff identifier not found to delete', '❌');
        return;
      }
      handleDeleteStaff(staffId);
    }

    function handleUnlockStaff(staffId) {
      if (!staffId) return;
      var staff = (state.staffList || []).find(function(s) {
        return (s.id || '').toUpperCase() === (staffId || '').toUpperCase();
      });
      var staffName = staff ? staff.name : staffId;

      if (!confirm('Are you sure you want to unlock staff member "' + staffName + '"?\n\nThis will reset their failed login attempts and allow them to log in immediately.')) {
        return;
      }

      apiCall('unlockStaff', { staffId: staffId }, function(res) {
        showToast('Staff "' + staffName + '" unlocked successfully!', '✓');
        loadStaffListForAdmin();
        var banner = document.getElementById('modalStaffLockedBanner');
        if (banner) banner.style.display = 'none';
      }, function(err) {
        showToast('Error unlocking staff: ' + (err.message || err), '❌');
      });
    }

    function handleUnlockStaffFromModal() {
      var staffId = (document.getElementById('editStaffId') && document.getElementById('editStaffId').value) || '';
      if (!staffId) {
        showToast('Staff identifier not found to unlock', '❌');
        return;
      }
      handleUnlockStaff(staffId);
    }

    function handleResetStaffDeviceSession(staffId) {
      if (!staffId) return;
      var staff = (state.staffList || []).find(function(s) {
        return (s.id || '').toUpperCase() === (staffId || '').toUpperCase();
      });
      var staffName = staff ? staff.name : staffId;

      if (!confirm('Are you sure you want to reset the active device session for "' + staffName + '"?\n\nThis will safely log them out from their current phone so they can log in on a new device.')) {
        return;
      }

      apiCall('unlockStaff', { staffId: staffId, clearSession: true }, function(res) {
        showToast('Staff "' + staffName + '" device session reset successfully! New device can now log in.', '✓');
        loadStaffListForAdmin();
        var banner = document.getElementById('modalStaffActiveSessionBanner');
        if (banner) banner.style.display = 'none';
      }, function(err) {
        showToast('Error resetting device: ' + (err.message || err), '❌');
      });
    }

    function handleResetStaffDeviceSessionFromModal() {
      var staffId = (document.getElementById('editStaffId') && document.getElementById('editStaffId').value) || '';
      if (!staffId) {
        showToast('Staff identifier not found to reset', '❌');
        return;
      }
      handleResetStaffDeviceSession(staffId);
    }

    if (typeof window !== 'undefined') {
      window.handleUnlockStaff = handleUnlockStaff;
      window.handleUnlockStaffFromModal = handleUnlockStaffFromModal;
      window.handleResetStaffDeviceSession = handleResetStaffDeviceSession;
      window.handleResetStaffDeviceSessionFromModal = handleResetStaffDeviceSessionFromModal;
    }

